import { useDispatch, useSelector } from "react-redux";
import type { AppDispatch, RootState } from "../../redux/store";
import { useNavigate, useParams } from "react-router-dom";
import { useEffect, useState } from "react";
import type { ProductCreateForm, ProductCreateFormError } from "../../types/type";
import { getProduct, updateProduct } from "../../redux/crudSlice";




const UpdateProduct: React.FC = () => {
    const { updateDetails, isLoading, upload_status } = useSelector((state: RootState) => state.crud);
    const dispatch = useDispatch<AppDispatch>();
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate()
    const [product, setProduct] = useState<ProductCreateForm>({
        name: "",
        category: "",
        price: "",
        description: "",
    })
    const [error, setError] = useState<ProductCreateFormError>({})
    const validation = () => {
        let error: ProductCreateFormError = {}
        if (!product.name) error.name = "Please enter your name";
        if (!product.category) error.category = "Please enter your email";
        if (!product.price) error.price = "Please enter your password";
        if (!product.description) error.description = "Please enter your phone";
        return error;
    }
    const postUserData = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const name = e.target.name;
        const value = e.target.value;

        if (name === "name") {
            if (value.trim().length === 0) {
                setProduct({ ...product, name: "" });
                setError({ ...error, name: "Please enter product name" });
            }
            else {
                setProduct({ ...product, name: value });
                setError({ ...error, name: "" });
            }
        }
        if (name === "category") {
            if (value.trim().length === 0) {
                setProduct({ ...product, category: "" });
                setError({ ...error, category: "Please enter category of product" });
            }
            else {
                setProduct({ ...product, category: value });
                setError({ ...error, category: "" });
            }
        }
        if (name === "price") {
            if (value.trim().length === 0) {
                setProduct({ ...product, price: "" });
                setError({ ...error, price: "Please enter price of product" });
            }
            else {
                setProduct({ ...product, price: value });
                setError({ ...error, price: "" });
            }
        }
        if (name === "description") {
            if (value.trim().length === 0) {
                setProduct({ ...product, description: "" });
                setError({ ...error, description: "Please enter description" });
            }
            else {
                setProduct({ ...product, description: value });
                setError({ ...error, description: "" });
            }
        }
    }

    const handleSubmit = (e: React.SyntheticEvent) => {
        e.preventDefault();
        const errors = validation();
        setError(errors);
        if (Object.keys(errors).length > 0) return null;
        if (!id) return;
        let data = {
            name: product.name,
            category: product.category,
            price: product.price,
            description: product.description,
            id: id,
        }
        dispatch(updateProduct(data));
    }

    useEffect(() => {
        if (id) {
            dispatch(getProduct(id));
        }
    }, [id, dispatch]);
    useEffect(() => {
        if (upload_status === "succeeded") {
            navigate("/Products");

        }
    }, [upload_status, navigate]);


    useEffect(() => {
        if (updateDetails !== null) {
            setProduct({
                name: updateDetails?.name || "",
                category: updateDetails?.category || "",
                price: updateDetails?.price || "",
                description: updateDetails?.description || "",
            })
        }
    }, [updateDetails])

    return (

        <>
            <div className="min-h-screen flex items-center justify-center bg-slate-950 px-6 relative overflow-hidden">
                {/* Dynamic Background Glows */}
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-pink-600/10 blur-[120px] pointer-events-none"></div>
                <div className="absolute -top-[10%] -right-[10%] w-[300px] h-[300px] bg-violet-600/10 blur-[100px] pointer-events-none"></div>

                <div className="relative z-10 w-full max-w-md bg-white/5 border border-white/10 backdrop-blur-2xl p-10 rounded-[2.5rem] shadow-2xl">
                    {/* Header Section */}
                    <div className="mb-10 text-center">
                        <div className="w-16 h-16 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl group">
                            <span className="text-pink-500 text-3xl group-hover:scale-110 transition-transform duration-300">⚙️</span>
                        </div>
                        <h2 className="text-3xl font-black text-white tracking-tighter uppercase mb-2">
                            Modify <span className="text-pink-500">Asset</span>
                        </h2>
                        <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.25em]">Update product information</p>
                    </div>

                    <form onSubmit={handleSubmit} className="space-y-5">
                        {/* Name Input */}
                        <div className="group">
                            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">Product Identity</label>
                            <input
                                type="text"
                                name="name"
                                value={product.name}
                                onChange={(e) => postUserData(e)}
                                className="w-full bg-slate-900/50 border border-white/10 rounded-2xl py-3.5 px-6 text-sm text-white placeholder:text-slate-700 focus:outline-none focus:ring-2 focus:ring-pink-500/50 focus:border-pink-500/50 transition-all duration-300 group-hover:border-white/20"
                                placeholder="Product Name"
                                required
                            />
                            {error.name && <span className="text-[9px] font-bold text-rose-500 uppercase tracking-widest mt-1 ml-1">{error.name}</span>}
                        </div>

                        {/* Category Input */}
                        <div className="group">
                            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">Collection</label>
                            <input
                                type="text"
                                name="category"
                                value={product.category}
                                onChange={(e) => postUserData(e)}
                                className="w-full bg-slate-900/50 border border-white/10 rounded-2xl py-3.5 px-6 text-sm text-white placeholder:text-slate-700 focus:outline-none focus:ring-2 focus:ring-pink-500/50 focus:border-pink-500/50 transition-all duration-300 group-hover:border-white/20"
                                placeholder="Category"
                                required
                            />
                            {error.category && <span className="text-[9px] font-bold text-rose-500 uppercase tracking-widest mt-1 ml-1">{error.category}</span>}
                        </div>

                        {/* Price Input */}
                        <div className="group">
                            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">Valuation (USD)</label>
                            <input
                                type="number"
                                name="price"
                                value={product.price}
                                onChange={(e) => postUserData(e)}
                                className="w-full bg-slate-900/50 border border-white/10 rounded-2xl py-3.5 px-6 text-sm text-white placeholder:text-slate-700 focus:outline-none focus:ring-2 focus:ring-pink-500/50 focus:border-pink-500/50 transition-all duration-300 group-hover:border-white/20"
                                placeholder="0.00"
                                required
                            />
                            {error.price && <span className="text-[9px] font-bold text-rose-500 uppercase tracking-widest mt-1 ml-1">{error.price}</span>}
                        </div>

                        {/* Description Input */}
                        <div className="group">
                            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">Specifications</label>
                            <textarea
                                name="description"
                                value={product.description}
                                onChange={(e) => postUserData(e)}
                                rows={3}
                                className="w-full bg-slate-900/50 border border-white/10 rounded-2xl py-3.5 px-6 text-sm text-white placeholder:text-slate-700 focus:outline-none focus:ring-2 focus:ring-pink-500/50 focus:border-pink-500/50 transition-all duration-300 group-hover:border-white/20 resize-none"
                                placeholder="Description..."
                                required
                            />
                            {error.description && <span className="text-[9px] font-bold text-rose-500 uppercase tracking-widest mt-1 ml-1">{error.description}</span>}
                        </div>

                        {/* Submit Button */}
                        <button
                            type="submit"
                            className="w-full mt-4 flex items-center justify-center gap-3 bg-white text-slate-950 py-4 rounded-2xl font-black uppercase text-[11px] tracking-[0.2em] shadow-xl transition-all hover:bg-pink-500 hover:text-white hover:shadow-pink-500/30 hover:-translate-y-1 active:scale-95 disabled:opacity-50"
                            disabled={isLoading}
                        >
                            {isLoading ? (
                                <div className="w-5 h-5 border-2 border-slate-950 border-t-transparent rounded-full animate-spin"></div>
                            ) : (
                                "Update Details"
                            )}
                        </button>
                    </form>
                </div>
            </div>

        </>
    )

}

export default UpdateProduct;